-- =====================================================================
-- SenPaie — Conventions collectives et salaires catégoriels minimums
-- Source : « Nouveaux barèmes des salaires catégoriels dans le secteur privé
-- à partir du 1er janvier 2020 » (Commission mixte paritaire du 30/12/2019,
-- Ministère du Travail). Revalorisation : +8 % catégories 1 à 3, +5 % au-delà.
-- Salaire mensuel = base 173,33 h. Taux horaires convertis : horaire × 173,33.
-- Boulangerie non industrielle : taux journaliers, mensuel indicatif = × 26 jours.
-- =====================================================================

create table if not exists public.conventions_collectives (
  id uuid primary key default gen_random_uuid(),
  code text not null unique,
  nom text not null,
  date_effet date not null default '2020-01-01',
  source text,
  created_at timestamptz not null default now()
);
create table if not exists public.categories_conventionnelles (
  id uuid primary key default gen_random_uuid(),
  convention_id uuid not null references public.conventions_collectives(id) on delete cascade,
  college text not null,
  categorie text not null,
  ordre integer not null,
  unite text not null check (unite in ('mensuel','horaire','journalier')),
  taux_horaire numeric(12,4),
  taux_journalier numeric(12,3),
  salaire_mensuel numeric(14,0) not null check (salaire_mensuel > 0),
  corrige boolean not null default false,
  unique (convention_id, college, categorie)
);
create index if not exists idx_cat_conv on public.categories_conventionnelles(convention_id, ordre);

alter table public.conventions_collectives enable row level security;
alter table public.categories_conventionnelles enable row level security;
drop policy if exists conv_select on public.conventions_collectives;
create policy conv_select on public.conventions_collectives for select to authenticated using (true);
drop policy if exists conv_admin on public.conventions_collectives;
create policy conv_admin on public.conventions_collectives for all to authenticated using (public.is_platform_admin()) with check (public.is_platform_admin());
drop policy if exists catconv_select on public.categories_conventionnelles;
create policy catconv_select on public.categories_conventionnelles for select to authenticated using (true);
drop policy if exists catconv_admin on public.categories_conventionnelles;
create policy catconv_admin on public.categories_conventionnelles for all to authenticated using (public.is_platform_admin()) with check (public.is_platform_admin());

-- Rattachement des entreprises et employés
alter table public.entreprises add column if not exists convention_id uuid references public.conventions_collectives(id) on delete set null;
alter table public.employes add column if not exists convention_id uuid references public.conventions_collectives(id) on delete set null;
alter table public.employes add column if not exists categorie_conv_id uuid references public.categories_conventionnelles(id) on delete set null;


