with d as (select j from _d),
ins as (insert into public.conventions_collectives(code, nom, source)
  select e->>0, e->>1, 'Barèmes catégoriels secteur privé – 1er janvier 2020' from d, jsonb_array_elements(j->'c') e
  on conflict (code) do update set nom = excluded.nom returning id, code)
select count(*) from ins;

with d as (select j from _d)
insert into public.categories_conventionnelles(convention_id, college, categorie, ordre, unite, taux_horaire, taux_journalier, salaire_mensuel, corrige)
select cc.id, d.j->'k'->>((r->>1)::int), r->>2, (r->>3)::int,
       case r->>4 when 'M' then 'mensuel' when 'H' then 'horaire' else 'journalier' end,
       case when r->>4 = 'H' then (r->>5)::numeric end, case when r->>4 = 'J' then (r->>5)::numeric end,
       (r->>6)::numeric, (r->>7) = '1'
from d cross join lateral jsonb_array_elements(d.j->'r') r
join public.conventions_collectives cc on cc.code = ((select j from _d)->'c'->((r->>0)::int)->>0)
on conflict (convention_id, college, categorie) do update set ordre = excluded.ordre, unite = excluded.unite,
  taux_horaire = excluded.taux_horaire, taux_journalier = excluded.taux_journalier, salaire_mensuel = excluded.salaire_mensuel, corrige = excluded.corrige;
-- =====================================================================
-- SenPaie — Méthode de calcul de l'IR alignée sur le barème mensuel DGID
-- Vérifiée sur les 4 951 lignes × 9 colonnes de parts du « Barème mensuel
-- des retenues à la source sur salaires » (0 écart) :
--   net mensuel = brut imposable − min(30 % ; 75 000), arrondi au millier inférieur
--   IR annuel   = barème art. 173 sur (net mensuel × 12) − réduction famille
--   IR mensuel  = IR annuel / 12, arrondi à l'unité
-- Les cotisations IPRES ne sont PAS déduites avant l'abattement.
-- =====================================================================
update public.parametres_legaux
   set valeur = valeur
     || jsonb_build_object('ir', (valeur->'ir') || '{"abattement_plafond_mensuel":75000,"arrondi_base":1000,"deduire_retraite":false}'::jsonb),
       source = coalesce(source,'') || ' ; méthode IR conforme au barème mensuel DGID'
 where cle = 'paie_senegal';

-- Pour le calcul des parts selon l'annexe 1 du Guide fiscal des PME
comment on column public.employes.conjoint_sans_revenu is 'Non utilisé pour les parts (règle DGID : marié = 1,5 part de base).';

select (select count(*) from public.conventions_collectives) conventions, (select count(*) from public.categories_conventionnelles) categories,
       (select valeur->'ir'->>'abattement_plafond_mensuel' from public.parametres_legaux limit 1) abattement_mensuel;
